"""The example simulation report the wiki embeds is current and says what the wiki says it shows.

Pins (2026-10-22, package p25) on ``docs/assets/other/simulation_report_ernie.html``, the page
``docs/wiki/reports.md`` embeds in an iframe. It is rebuilt from Dataset 000
``sub-ernie/Simulations/AF3_PO10_and_AF4_Oz`` by the report generator alone (no FEM)::

    simnibs_python -m tit.reporting.generators.simulation /data/000 ernie AF3_PO10_and_AF4_Oz --out <dir>

and copied over the asset. Checked here, without the dataset:

* it was generated by this release line: the generator stamp's major.minor is
  ``tit.__version__``'s (the page stamped 3.0.1 predated the 2026-10 report fixes);
* it has the four sections the report always writes (verdict, montage, field, technical) and the
  field section holds the envelope figure;
* its numbers are coherent: grey-matter median <= 99.9th percentile <= maximum, and the
  headline is the 99.9th percentile tile;
* it shows what the wiki's caption promises: sub-ernie, AF3-PO10 and AF4-Oz, 1 mA per channel,
  anisotropic conductivity from the subject's DTI tensor.

The values themselves come from the real files: ``tests/numerical/test_reports_realdata.py``
rebuilds every Dataset 000 report and checks its numbers against the NIfTIs.
Reproduce: ``.venv/bin/python -m pytest tests/test_docs_example_report.py -q``.
"""

from __future__ import annotations

import html as htmllib
import re
from pathlib import Path

import tit

REPO = Path(__file__).resolve().parents[1]
ASSET = REPO / "docs" / "assets" / "other" / "simulation_report_ernie.html"
WIKI = REPO / "docs" / "wiki" / "reports.md"


def _page() -> str:
    return ASSET.read_text(encoding="utf-8")


def _tile(page: str, label: str) -> float:
    match = re.search(rf"<dt>{re.escape(label)}</dt><dd><b>([\d.]+)<small>V/m", page)
    assert match, f"no '{label}' tile"
    return float(match.group(1))


def test_the_wiki_embeds_this_asset():
    assert "/assets/other/simulation_report_ernie.html" in WIKI.read_text()
    assert ASSET.is_file()


def test_the_example_was_generated_by_this_release_line():
    page = _page()
    stamps = set(
        re.findall(r'<meta name="generator" content="TI-Toolbox (\d+\.\d+)\.\d+', page)
    )
    stamps |= set(re.findall(r"<dt>TI-Toolbox</dt><dd>(\d+\.\d+)\.\d+</dd>", page))
    major_minor = ".".join(tit.__version__.split(".")[:2])
    assert stamps == {major_minor}, (stamps, tit.__version__)


def test_the_example_has_every_section_and_the_envelope_figure():
    page = _page()
    for anchor in ("verdict", "montage", "field", "technical"):
        assert f'id="{anchor}-h"' in page, anchor
        assert f'href="#{anchor}"' in page, anchor
    field = page.split('id="field"', 1)[1].split("</section>", 1)[0]
    assert re.search(r'<img [^>]*src="data:image/webp;base64,', field)


def test_the_example_numbers_are_ordered_and_the_headline_is_the_p99_9():
    page = _page()
    median = _tile(page, "Grey matter median")
    p999 = _tile(page, "Grey matter 99.9th pct")
    peak = _tile(page, "Grey matter maximum")
    assert 0 < median <= p999 <= peak, (median, p999, peak)
    head = re.search(
        r'<h2 id="verdict-h">([\d.]+) V/m peak envelope in grey matter', page
    )
    assert head and float(head.group(1)) == p999


def test_the_example_shows_what_the_wiki_caption_promises():
    text = htmllib.unescape(re.sub(r"<[^>]+>", " ", _page()))
    assert "sub-ernie" in text
    assert "AF3–PO10 and AF4–Oz" in text
    assert "1 mA per channel" in text
    assert "anisotropic" in text and "from the subject's DTI tensor" in text
